import type { Session } from 'electron'

type PermissionSession = Pick<Session, 'setPermissionRequestHandler'>

/**
 * Admit renderer microphone/media requests while rejecting unrelated Chromium
 * permissions. macOS still owns the actual microphone grant through TCC.
 * The app's own UI may also write the clipboard (navigator.clipboard.writeText, e.g. the
 * artifact Copy button); a subframe such as an artifact preview may not.
 */
export function installMediaPermissionHandler(target: PermissionSession): void {
  target.setPermissionRequestHandler((_webContents, permission, callback, details) => {
    if (permission === 'clipboard-sanitized-write') {
      callback(details.isMainFrame)
      return
    }
    callback(permission === 'media')
  })
}

// Real Electron IPC, real model client, synthetic profile; only the external model is a fake.
import { app, BrowserWindow } from 'electron'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import type { AddressInfo } from 'node:net'
import { setupChatNextActionIpc } from '../chat-next-action'
import { setRemoteVisionServerSettings } from '../vision/remote-vision-server'
import { getDB } from '../database'

void app.whenReady().then(async () => {
  let window: BrowserWindow | undefined
  const requests: Record<string, unknown>[] = []
  const responses = ['Suggestion: "Compare the tradeoffs."', 'NONE', 'failure']
  const server = createServer((req, res) => {
    if (req.method === 'GET') {
      res
        .writeHead(200, { 'content-type': 'application/json' })
        .end(JSON.stringify({ data: [{ id: 'synthetic/text', object: 'model' }] }))
      return
    }
    if (req.method !== 'POST' || !req.url?.endsWith('/chat/completions')) {
      res.writeHead(404).end()
      return
    }
    let body = ''
    req.on('data', (part) => {
      body += String(part)
    })
    req.on('end', () => {
      let payload: Record<string, unknown>
      try {
        payload = JSON.parse(body) as Record<string, unknown>
      } catch {
        res
          .writeHead(400, { 'content-type': 'application/json' })
          .end(JSON.stringify({ error: { message: 'Invalid JSON' } }))
        return
      }
      requests.push(payload)
      const content = responses.shift() ?? 'NONE'
      if (content === 'failure') {
        res
          .writeHead(400, { 'content-type': 'application/json' })
          .end(JSON.stringify({ error: { message: 'Synthetic model failure' } }))
      } else {
        res.writeHead(200, { 'content-type': 'text/event-stream' }).end(
          `data: ${JSON.stringify({
            choices: [{ delta: { content }, finish_reason: 'stop' }]
          })}\n\ndata: [DONE]\n\n`
        )
      }
    })
  })
  try {
    await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve))
    setRemoteVisionServerSettings({
      provider: 'openrouter',
      name: 'Synthetic text model',
      model: 'synthetic/text',
      endpoint: `http://127.0.0.1:${(server.address() as AddressInfo).port}`,
      apiKey: '<REDACTED>'
    })
    setupChatNextActionIpc()
    window = new BrowserWindow({
      show: false,
      webPreferences: { nodeIntegration: true, contextIsolation: false, sandbox: false }
    })
    await window.loadURL('data:text/html,<title>Synthetic suggestion test</title>')
    const suggest = (asked: unknown, answer: unknown): Promise<unknown> =>
      window!.webContents.executeJavaScript(
        `require('electron').ipcRenderer.invoke('chat:suggest-next', ${JSON.stringify(asked)}, ${JSON.stringify(answer)})`
      )
    assert.equal(await suggest(null, 'Answer'), null)
    assert.equal(requests.length, 0)
    assert.equal(await suggest('Compare these plans', 'Plan A is faster'), 'Compare the tradeoffs')
    const sent = requests[0]!
    assert.equal(sent.max_tokens, 40)
    assert.equal(sent.tools, undefined)
    const messages = sent.messages as { role: string; content: string }[]
    assert.ok(messages[0]!.content.includes('in this conversation'))
    assert.ok(messages[1]!.content.includes('Plan A is faster'))
    assert.equal(await suggest('Thank you', 'You are welcome'), null)
    assert.equal(await suggest('Compare these plans', 'Plan A is faster'), null)
    console.log('CHAT_NEXT_ACTION_NATIVE_PASSED')
  } catch (error) {
    console.error(error)
    process.exitCode = 1
  } finally {
    await new Promise<void>((resolve) => server.close(() => resolve()))
    getDB().close()
    window?.destroy()
    app.exit(process.exitCode ? 1 : 0)
  }
})

// Real action engine, browser host, Stop control and SQLite task history.
// Only the external model server is synthetic; stop while its plan request is in flight.
import { app } from 'electron'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import type { AddressInfo } from 'node:net'
import { getActionsRuntime } from '../actions/use-runtime'
import { controlVisionTask } from '../vision/vision-controller'
import { getTaskRun } from '../tasks/task-history'
import { getTaskRetryAvailability } from '../tasks/task-retry'
import { setRemoteVisionServerSettings } from '../vision/remote-vision-server'
import { disposeBrowserHost } from '../browser/browser-host'
import { getDB } from '../database'

void app.whenReady().then(async () => {
  let started!: () => void
  const planning = new Promise<void>((resolve) => {
    started = resolve
  })
  const server = createServer((req, res) => {
    req.resume()
    if (req.method === 'POST') {
      started()
      return
    }
    if (req.url?.includes('models')) {
      res
        .writeHead(200, { 'content-type': 'application/json' })
        .end(JSON.stringify({ data: [{ id: 'synthetic' }] }))
    } else {
      res.writeHead(200, { 'content-type': 'text/html' }).end('<label>Email<input></label>')
    }
  })
  try {
    await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve))
    const endpoint = `http://127.0.0.1:${(server.address() as AddressInfo).port}`
    setRemoteVisionServerSettings({
      provider: 'lmstudio',
      name: 'Synthetic local model',
      model: 'synthetic',
      endpoint
    })
    const runtime = getActionsRuntime()
    const proposed = await runtime.propose(
      {
        type: 'web_use',
        intent: 'Fill the synthetic form',
        args: { goal: 'Fill the synthetic form', url: endpoint },
        risk: 'mutate'
      },
      { source: 'chat' }
    )
    assert.ok(proposed.accepted)
    if (!proposed.accepted) throw new Error('Task was not accepted')
    // Let the startup drain finish, then deliver the normal worker wake-up.
    await new Promise<void>((resolve) => setImmediate(resolve))
    runtime.kick()
    await Promise.race([
      planning,
      runtime.waitForOutcome(proposed.id, 8000).then((outcome) => {
        throw new Error(JSON.stringify({ outcome, task: getTaskRun(proposed.id) }))
      })
    ])
    assert.equal(controlVisionTask('stop', proposed.id), true)
    assert.equal(getTaskRun(proposed.id)?.status, 'stopped')
    assert.ok(await runtime.waitForOutcome(proposed.id, 5000))
    assert.equal(
      getTaskRun(proposed.id)?.status,
      'stopped',
      'Late action completion must preserve Stop'
    )
    assert.equal(getTaskRetryAvailability(proposed.id).available, true)
    console.log('TASK_STOP_NATIVE_PASSED')
  } catch (error) {
    console.error(error)
    process.exitCode = 1
  } finally {
    disposeBrowserHost()
    server.closeAllConnections()
    await new Promise<void>((resolve) => server.close(() => resolve()))
    getDB().close()
    app.exit(process.exitCode ? 1 : 0)
  }
})

// Real Electron page, CDP, Playwright MCP, task loop and model HTTP client. The external
// browser protocol simulates Chrome refusing debugger access after an extension frame opens.
import { app, BrowserWindow } from 'electron'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import type { AddressInfo } from 'node:net'
import type { BrowserLink } from '../extension-bridge/bridge-socket'
import type { SocketEvent } from '../extension-bridge/bridge-socket-protocol'
import { createExtensionBrowserHost } from '../browser/extension-browser-host'
import { setRemoteVisionServerSettings } from '../vision/remote-vision-server'
import { getDB } from '../database'

const BLOCKED = 'Cannot access a chrome-extension:// URL of different extension'
const FORM =
  '<label>Business Email<input aria-label="Business Email" id="email"></label><button onclick="document.querySelector(\'output\').textContent=\'Application ready\'">Continue</button><output></output>'

void app.whenReady().then(async () => {
  let window: BrowserWindow | undefined
  let blocked = false
  let blockAfterFill = true
  let fallbackSnapshots = 0
  let pageActions = 0
  const events = new Set<(event: SocketEvent) => void>()
  const server = createServer((req, res) => {
    if (req.url === '/form') {
      res.writeHead(200, { 'content-type': 'text/html' }).end(FORM)
      return
    }
    if (req.method === 'GET') {
      res
        .writeHead(200, { 'content-type': 'application/json' })
        .end(JSON.stringify({ data: [{ id: 'synthetic/text' }] }))
      return
    }
    let body = ''
    req.on('data', (chunk) => {
      body += String(chunk)
    })
    req.on('end', () => {
      void (async () => {
        const request = JSON.parse(body)
        const contentParts = request.messages.at(-1).content
        const prompt =
          typeof contentParts === 'string'
            ? contentParts
            : contentParts
                .filter((part: { type: string }) => part.type === 'text')
                .map((part: { text: string }) => part.text)
                .join('\n')
        const snapshot =
          prompt.split('<untrusted_page_snapshot>')[1]?.split('</untrusted_page_snapshot>')[0] ?? ''
        const complete = snapshot.includes('Application ready')
        const filled = snapshot.includes('synthetic@example.test')
        // The external browser loses debugger access after the email field was filled.
        if (blockAfterFill && filled && !blocked) {
          blocked = true
          window!.webContents.debugger.detach()
        }
        const ref = complete
          ? null
          : filled
            ? /button "Continue" \[ref=([^\]]+)\]/.exec(snapshot)?.[1]
            : /textbox "Business Email" \[ref=([^\]]+)\]/.exec(snapshot)?.[1]
        assert.ok(complete || ref, `Missing form control in synthetic model input: ${snapshot}`)
        const content = JSON.stringify({
          action: complete ? 'done' : filled ? 'click' : 'type',
          phase_id: null,
          element: complete ? null : filled ? 'Continue' : 'Business Email',
          ref: ref ?? null,
          text: !complete && !filled ? 'synthetic@example.test' : null,
          key: null,
          values: null,
          start_element: null,
          start_ref: null,
          end_element: null,
          end_ref: null,
          url: null,
          evidence_ref: null,
          evidence_text: complete ? 'Application ready' : null,
          reason: '',
          summary: complete ? 'Application ready' : filled ? 'Continue' : 'Fill email'
        })
        res
          .writeHead(200, { 'content-type': 'text/event-stream' })
          .end(
            `data: ${JSON.stringify({ choices: [{ delta: { content }, finish_reason: 'stop' }] })}\n\ndata: [DONE]\n\n`
          )
      })().catch((error) => {
        res
          .writeHead(500, { 'content-type': 'application/json' })
          .end(JSON.stringify({ error: { message: String(error) } }))
      })
    })
  })
  try {
    await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve))
    const endpoint = `http://127.0.0.1:${(server.address() as AddressInfo).port}`
    setRemoteVisionServerSettings({
      provider: 'openrouter',
      name: 'Synthetic',
      model: 'synthetic/text',
      endpoint,
      apiKey: '<REDACTED>'
    })
    window = new BrowserWindow({ show: false })
    const contents = window.webContents
    contents.debugger.on('message', (_event, method, params, sessionId) => {
      for (const listener of events)
        listener({
          event: 'cdp.event',
          tabId: 42,
          data: { method, params, ...(sessionId ? { sessionId } : {}) }
        })
    })
    contents.debugger.on('detach', (_event, reason) => {
      for (const listener of events)
        listener({ event: 'cdp.detached', tabId: 42, data: { reason } })
    })
    const link: BrowserLink = {
      browser: { id: 'synthetic', name: 'Synthetic Chromium', publicKey: 'synthetic', pairedAt: 1 },
      async request(op, args = {}) {
        if (op === 'browser.caps') return { cdp: true }
        if (op === 'tab.adopt') return { tabId: 42, url: `${endpoint}/form`, title: 'Form' }
        if (op === 'cdp.attach') {
          if (blocked) throw new Error(BLOCKED)
          if (!contents.debugger.isAttached()) contents.debugger.attach('1.3')
          return {}
        }
        if (op === 'cdp.detach') {
          contents.debugger.detach()
          return {}
        }
        if (op === 'cdp.send')
          return contents.debugger.sendCommand(
            String(args.method),
            args.params,
            args.sessionId as string | undefined
          )
        if (op === 'page.call') {
          const input = args.args as Record<string, unknown>
          if (args.tool === 'browser_snapshot') {
            fallbackSnapshots += 1
            const page = await contents.executeJavaScript(
              '({email: document.querySelector("input").value, result: document.querySelector("output").textContent})'
            )
            return {
              isError: false,
              text: `- textbox "Business Email" [ref=fresh-email]: ${page.email}\n- button "Continue" [ref=fresh-continue]\n- status: ${page.result}`
            }
          }
          if (args.tool === 'browser_type') {
            assert.equal(input.target, 'fresh-email')
            await contents.executeJavaScript(
              `document.querySelector('input').value=${JSON.stringify(input.text)}`
            )
          } else if (args.tool === 'browser_click') {
            assert.equal(input.target, 'fresh-continue')
            await contents.executeJavaScript("document.querySelector('button').click()")
          } else throw new Error(`Unexpected page tool ${args.tool}`)
          pageActions += 1
          return { isError: false, text: 'Action completed' }
        }
        throw new Error(`Unexpected browser operation ${op}`)
      },
      onEvent(listener) {
        events.add(listener)
        return () => {
          events.delete(listener)
        }
      },
      onClose: () => () => {},
      close: () => {}
    }
    for (const taskId of ['blocked-after-fill', 'blocked-at-start']) {
      await window.loadURL(`${endpoint}/form`)
      const result = await createExtensionBrowserHost(() => link, 42).runTask({
        goal: 'Fill Business Email with synthetic@example.test and click Continue',
        taskId,
        journeyId: taskId,
        checkpoint: {
          taskId,
          steps: [],
          plan: { version: 1, phases: [{ id: 'form', title: 'Fill form' }] }
        }
      })
      assert.equal(result.ok, true, result.summary)
      assert.equal(result.finalUrl, `${endpoint}/form`)
      assert.equal(
        await contents.executeJavaScript('document.querySelector("input").value'),
        'synthetic@example.test'
      )
      assert.equal(
        await contents.executeJavaScript('document.querySelector("output").textContent'),
        'Application ready'
      )
      assert.equal(pageActions, taskId === 'blocked-after-fill' ? 1 : 3)
      blockAfterFill = false
    }
    assert.ok(fallbackSnapshots >= 6)
    console.log('WEB_USE_DEBUGGER_NATIVE_PASSED')
  } catch (error) {
    console.error(error)
    process.exitCode = 1
  } finally {
    await new Promise<void>((resolve) => server.close(() => resolve()))
    getDB().close()
    window?.destroy()
    app.exit(process.exitCode ? 1 : 0)
  }
})

// Real task host, model client, page session and task history. Only the external browser
// extension and HTTP model provider use contract-faithful synthetic boundaries.
import { app, BrowserWindow } from 'electron'
import { registerBrowserViewIpc, disposeBrowserHost } from '../browser/browser-host'
import { controlVisionTask } from '../vision/vision-controller'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import type { AddressInfo } from 'node:net'
import type { BrowserLink } from '../extension-bridge/bridge-socket'
import { createExtensionBrowserHost } from '../browser/extension-browser-host'
import type { WebTaskResult } from '../browser/browser-rail'
import { setRemoteVisionServerSettings } from '../vision/remote-vision-server'
import { getTaskRun } from '../tasks/task-history'
import { getDB } from '../database'

function decision(action: string, ref: string | null): Record<string, unknown> {
  return {
    action,
    phase_id: null,
    element: ref ? 'Place order' : null,
    ref,
    text: null,
    key: null,
    values: null,
    start_element: null,
    start_ref: null,
    end_element: null,
    end_ref: null,
    url: null,
    evidence_ref: null,
    evidence_text: null,
    reason: '',
    summary: `${action} ${ref ?? ''}`.trim()
  }
}
const done = { ...decision('done', null), phase_id: 'read', evidence_text: 'Order placed' }

async function until(check: () => boolean): Promise<void> {
  for (let i = 0; i < 200 && !check(); i += 1) {
    await new Promise((resolve) => setTimeout(resolve, 25))
  }
  assert.ok(check(), 'Timed out waiting for the synthetic browser')
}

void app.whenReady().then(async () => {
  let window: BrowserWindow | undefined
  let holdModel = false
  let modelStarted!: () => void
  const pendingModel = new Promise<void>((resolve) => {
    modelStarted = resolve
  })
  let modelRequests = 0
  let modelFails = true
  // Queued decisions for the uncertain-action runs; empty means the visual fallback reply.
  const replies: Array<Record<string, unknown>> = []
  // What the synthetic extension answers for an input action, and the inputs it received.
  let actionResult: Record<string, unknown> | null = null
  const actions: string[] = []
  const server = createServer((req, res) => {
    req.resume()
    if (req.method === 'GET') {
      res.writeHead(200, { 'content-type': 'application/json' })
      res.end(JSON.stringify({ data: [{ id: 'synthetic/text', object: 'model' }] }))
      return
    }
    if (holdModel) {
      modelStarted()
      return
    }
    modelRequests += 1
    if (modelFails) {
      res.writeHead(402, { 'content-type': 'application/json' })
      res.end(JSON.stringify({ error: { message: 'Insufficient credits' } }))
      return
    }
    const content = JSON.stringify(
      replies.shift() ?? {
        action: 'fallback',
        phase_id: null,
        element: null,
        ref: null,
        text: null,
        key: null,
        values: null,
        start_element: null,
        start_ref: null,
        end_element: null,
        end_ref: null,
        url: null,
        evidence_ref: null,
        evidence_text: null,
        reason: 'The notification content is drawn on a canvas with no readable controls.',
        summary: ''
      }
    )
    res.writeHead(200, { 'content-type': 'text/event-stream' })
    res.end(
      `data: ${JSON.stringify({ choices: [{ delta: { content }, finish_reason: 'stop' }] })}\n\ndata: [DONE]\n\n`
    )
  })
  const link: BrowserLink = {
    browser: {
      id: 'synthetic-browser',
      name: 'Synthetic browser',
      publicKey: 'synthetic',
      pairedAt: 1
    },
    async request(op, args = {}) {
      if (op === 'browser.caps') return { cdp: false }
      if (op === 'tab.adopt')
        return { tabId: args.tabId, url: 'https://synthetic.test/', title: 'Synthetic page' }
      if (op === 'page.call' && actionResult && args.tool !== 'browser_snapshot') {
        actions.push(String(args.tool))
        return actionResult
      }
      if (op === 'page.call' && actionResult) {
        return { text: '- button "Place order" [ref=e1]\n- text "Order placed"', isError: false }
      }
      if (op === 'page.call') return { text: '- button "Notifications" [ref=e1]', isError: false }
      if (op === 'cdp.detach') return {}
      throw new Error(`Unexpected browser operation: ${op}`)
    },
    onEvent: () => () => {},
    onClose: () => () => {},
    close: () => {}
  }
  try {
    await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve))
    setRemoteVisionServerSettings({
      provider: 'openrouter',
      name: 'Synthetic model',
      model: 'synthetic/text',
      endpoint: `http://127.0.0.1:${(server.address() as AddressInfo).port}`,
      apiKey: '<REDACTED>'
    })
    const run = (taskId: string): Promise<WebTaskResult> =>
      createExtensionBrowserHost(() => link, 42).runTask({
        goal: 'Read unread notifications',
        taskId,
        journeyId: taskId,
        checkpoint: {
          taskId,
          steps: [],
          plan: { version: 1, phases: [{ id: 'read', title: 'Read notifications' }] }
        }
      })
    const failed = await run('model-unavailable')
    assert.equal(failed.ok, false)
    assert.match(failed.summary, /402/)
    assert.match(failed.summary, /Insufficient credits/)
    assert.doesNotMatch(failed.summary, /visual control|Switch Tasks/)
    assert.equal(getTaskRun('model-unavailable')?.summary, failed.summary)
    modelFails = false
    const visual = await run('visual-page')
    assert.equal(visual.ok, false)
    assert.match(visual.summary, /canvas with no readable controls/)
    assert.equal(modelRequests, 2)

    // An action the page did not confirm may have run: it is never sent again, also when the
    // next snapshot gives the same control a new reference, and also from an older extension.
    for (const result of [
      { text: 'The action may have run.', isError: false, uncertain: true },
      { text: 'The page did not answer.', isError: true }
    ]) {
      actionResult = result
      actions.length = 0
      replies.push(decision('click', 'e1'), decision('click', 'e2'), done)
      const uncertain = await run(`uncertain-${result.isError ? 'legacy' : 'flag'}`)
      assert.equal(uncertain.ok, true, uncertain.summary)
      assert.deepEqual(actions, ['browser_click'])
    }

    // Two unconfirmed inputs in a row: the task waits for the user before the next decision.
    actionResult = { text: 'The action may have run.', isError: false, uncertain: true }
    actions.length = 0
    replies.push(decision('click', 'e1'), { ...decision('press_key', null), key: 'Enter' }, done)
    const requestsBefore = modelRequests
    const paused = run('uncertain-twice')
    await until(() => actions.length === 2)
    await new Promise((resolve) => setTimeout(resolve, 500))
    assert.equal(modelRequests, requestsBefore + 2, 'No decision while waiting for the user')
    assert.equal(controlVisionTask('resume', 'uncertain-twice'), true)
    assert.equal((await paused).ok, true)
    assert.deepEqual(actions, ['browser_click', 'browser_press_key'])
    actionResult = null
    holdModel = true
    const running = run('external-active')
    await pendingModel
    registerBrowserViewIpc()
    window = new BrowserWindow({
      show: false,
      webPreferences: { nodeIntegration: true, contextIsolation: false, sandbox: false }
    })
    await window.loadURL('data:text/html,<title>Synthetic browser task</title>')
    assert.equal(
      await window.webContents.executeJavaScript(
        "require('electron').ipcRenderer.invoke('browser:reopen', 'external-active')"
      ),
      false
    )
    const sessions = await window.webContents.executeJavaScript(
      "require('electron').ipcRenderer.invoke('browser:get-sessions')"
    )
    assert.deepEqual(
      sessions.sessions,
      [],
      'Opening task details must not allocate a duplicate browser page'
    )
    controlVisionTask('stop', 'external-active')
    await running
    console.log('WEB_USE_FAILURE_NATIVE_PASSED')
  } catch (error) {
    console.error(error)
    process.exitCode = 1
  } finally {
    window?.destroy()
    disposeBrowserHost()
    server.closeAllConnections()
    await new Promise<void>((resolve) => server.close(() => resolve()))
    getDB().close()
    app.exit(process.exitCode ? 1 : 0)
  }
})

// Synthetic PDF fixture used by the multimodal integration journey.
export const SYNTHETIC_PDF = Buffer.from(
  '',
  'base64'
)

/**
 * A one-page PDF whose text is a real text layer (standard Helvetica), so it is read without OCR on
 * every platform. SYNTHETIC_PDF's page needs OCR, which Linux CI has no engine for.
 */
export function textLayerPdf(line: string): Buffer {
  const text = `BT /F1 12 Tf 72 720 Td (${line.replace(/[()\\]/g, '')}) Tj ET`
  const objects = [
    '<</Type/Catalog/Pages 2 0 R>>',
    '<</Type/Pages/Kids[3 0 R]/Count 1>>',
    '<</Type/Page/Parent 2 0 R/MediaBox[0 0 612 792]/Contents 4 0 R/Resources<</Font<</F1 5 0 R>>>>>>',
    `<</Length ${text.length}>>\nstream\n${text}\nendstream`,
    '<</Type/Font/Subtype/Type1/BaseFont/Helvetica>>'
  ]
  let body = '%PDF-1.4\n'
  const offsets: number[] = []
  objects.forEach((object, i) => {
    offsets.push(body.length)
    body += `${i + 1} 0 obj\n${object}\nendobj\n`
  })
  const xref = body.length
  body += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`
  for (const offset of offsets) body += `${String(offset).padStart(10, '0')} 00000 n \n`
  body += `trailer\n<</Size ${objects.length + 1}/Root 1 0 R>>\nstartxref\n${xref}\n%%EOF`
  return Buffer.from(body, 'latin1')
}

// A real Electron main process, real SQLite profile, HTTP, WebSockets and encryption.
// The seeded pairing represents a browser paired before this app restart.
import { app } from 'electron'
import assert from 'node:assert/strict'
import fs from 'node:fs/promises'
import path from 'node:path'
import http from 'node:http'
import { randomUUID } from 'node:crypto'
import { once } from 'node:events'
import { WebSocket } from 'ws'
import {
  generateKeyPair,
  exportPublicKey,
  importPublicKey,
  deriveSessionKey,
  seal,
  open,
  requestAad,
  responseAad
} from '../bridge-protocol'
import { helloAad, readyAad, newNonce, parseReady } from '../bridge-socket-protocol'

const timer = setTimeout(() => app.exit(1), 45_000)
app
  .whenReady()
  .then(async () => {
    const desktop = await generateKeyPair(true)
    const browser = await generateKeyPair(true)
    const device = 'native-browser-001'
    const profile = app.getPath('userData')
    await fs.mkdir(profile, { recursive: true })
    await fs.writeFile(
      path.join(profile, 'extension-bridge.json'),
      JSON.stringify({
        version: 1,
        key: {
          enc: 'none',
          data: JSON.stringify(await crypto.subtle.exportKey('jwk', desktop.privateKey))
        },
        browsers: [
          {
            id: device,
            name: 'Synthetic browser',
            publicKey: await exportPublicKey(browser.publicKey),
            pairedAt: Date.now()
          }
        ]
      })
    )
    const { handleExtensionBridge, handleExtensionUpgrade } = await import('../bridge-http')
    const { getBrowserLinks, listBridgeBrowsers, addBrowserLink } =
      await import('../bridge-electron')
    const server = http.createServer((req, res) => {
      void handleExtensionBridge(
        req,
        res,
        new URL(req.url!, 'http://localhost').pathname,
        req.method!
      )
    })
    server.on('upgrade', (req, socket, head) => {
      if (!handleExtensionUpgrade(req, socket, head)) socket.destroy()
    })
    server.listen(0, '127.0.0.1')
    await once(server, 'listening')
    const port = (server.address() as { port: number }).port
    const base = `http://127.0.0.1:${port}`
    const origin = 'chrome-extension://abcdefghijklmnopabcdefghijklmnop'
    const info = (await (
      await fetch(base + '/v1/extension/info', { headers: { origin } })
    ).json()) as { publicKey: string }
    const key = await deriveSessionKey(
      browser.privateKey,
      (await importPublicKey(info.publicKey))!,
      device
    )
    const call = async (
      method: string,
      params: Record<string, unknown> = {}
    ): Promise<{ status: number; body: { result?: unknown; error?: string } }> => {
      const id = randomUUID()
      const sealed = await seal(key, requestAad(device), { id, ts: Date.now(), method, params })
      const response = await fetch(base + '/v1/extension/rpc', {
        method: 'POST',
        headers: { origin, 'content-type': 'application/json' },
        body: JSON.stringify({ v: 1, d: device, ...sealed })
      })
      const body = await response.json()
      if (response.status !== 200) return { status: response.status, body }
      return {
        status: response.status,
        body: (await open(key, responseAad(device, id), body)) as {
          result?: unknown
          error?: string
        }
      }
    }
    assert.equal(
      (await fetch(base + '/v1/extension/info', { headers: { origin: 'https://web.test' } }))
        .status,
      403
    )
    assert.equal(
      (await fetch(base + '/v1/extension/pair', { method: 'POST', body: '{}' })).status,
      403
    )
    assert.equal(
      (await fetch(base + '/v1/extension/pair', { method: 'POST', headers: { origin }, body: '{' }))
        .status,
      400
    )
    assert.equal((await fetch(base + '/v1/extension/other', { headers: { origin } })).status, 404)
    assert.equal((await call('state')).status, 200)
    for (const section of ['remote', 'tasks', 'tools', 'connectors', 'voice', 'image']) {
      const reply = await call('settings.get', { section })
      assert.equal(reply.status, 200)
      assert.ok(!reply.body.error, `${section}: ${JSON.stringify(reply.body)}`)
    }
    assert.equal(
      (await call('settings.set', { section: 'voice', patch: { ttsEnabled: true } })).status,
      200
    )
    const conversation = {
      id: 'native-chat',
      title: 'Synthetic chat',
      turns: [{ role: 'user', content: 'Hello' }]
    }
    const put = await call('conversations.put', { conversation })
    assert.ok(!put.body.error, JSON.stringify(put))
    await call('conversations.put', { conversation })
    const listed = await call('conversations.list')
    assert.ok(JSON.stringify(listed.body).includes('Hello'))
    assert.ok(!(await call('conversations.delete', { id: conversation.id })).body.error)
    assert.ok(!(await call('tools.list')).body.error)
    assert.ok((await call('settings.get', { section: 'invalid' })).body.error)
    const ws = new WebSocket(`ws://127.0.0.1:${port}/v1/extension/socket?d=${device}`, { origin })
    await once(ws, 'open')
    const readyMessage = once(ws, 'message')
    const nonce = newNonce()
    ws.send(JSON.stringify(await seal(key, helloAad(device), { nonce, ts: Date.now() })))
    const [raw] = await readyMessage
    assert.ok(parseReady(await open(key, readyAad(device, nonce), JSON.parse(String(raw)))))
    assert.equal(listBridgeBrowsers()[0]?.connected, true)
    const link = getBrowserLinks()[0]!
    const disconnected = once(ws, 'close')
    assert.ok(!(await call('unpair')).body.error)
    await disconnected
    assert.deepEqual(listBridgeBrowsers(), [])
    assert.deepEqual(getBrowserLinks(), [])
    await assert.rejects(link.request('tabs.list'), /disconnected/)
    // A handshake that finishes after unpair must not restore eligibility for tasks.
    addBrowserLink(link)
    assert.deepEqual(getBrowserLinks(), [])
    assert.equal((await call('state')).status, 401)
    await new Promise<void>((resolve) => server.close(() => resolve()))
    console.log('EXTENSION_BRIDGE_NATIVE_PASSED')
    clearTimeout(timer)
    app.exit(0)
  })
  .catch((error) => {
    console.error(error)
    clearTimeout(timer)
    app.exit(1)
  })

/** Pro owns paired-device consent. Core owns only this narrow policy port. */
export type RemoteTaskPermissionProvider = (deviceId: string) => boolean

let provider: RemoteTaskPermissionProvider | null = null

export function registerRemoteTaskPermissionProvider(
  next: RemoteTaskPermissionProvider | null
): void {
  provider = next
}

export function mayRunRemoteTask(deviceId: string): boolean {
  return provider?.(deviceId) === true
}
